style.css:
@-moz-document domain("www.bing.com") {
/* Hide Bing logo and search options */
  #sb_form_q,
  #sb_form_go,
  #sb_form_gl,
  #sb_form_area,
  #sb_form_search,
  #sb_form_q_container,
  #sb_form_search_button,
  #sb_form_logo,
  #sb_form_txt,
  #sb_form_cbs,
  #sb_form_q_wrap,
  #sb_form_q_wrap_container,
  #sb_form_search_wrapper,
  #sb_form_search_wrapper_container,
  #sb_form_footer,
  #sb_form_footer_container,
  .b_searchbox,
  .b_searchboxForm,
  .b_searchboxInput,
  .b_searchboxButton,
  .b_searchboxLogo,
  .b_searchboxText,
  .b_searchboxCBS,
  .b_searchboxQWrap,
  .b_searchboxQWrapContainer,
  .b_searchboxSearchWrapper,
  .b_searchboxSearchWrapperContainer,
  .b_searchboxFooter,
  .b_searchboxFooterContainer {
    display: none !important;
  }

  /* Add Google logo and search bar */
  #sb_form_q_container::before {
    content: "";
    display: block;
    width: 272px;
    height: 92px;
    background-image: url("https://www.google.com/images/branding/googlelogo/1x/googlelogo_color_272x92dp.png");
    background-size: contain;
    background-repeat: no-repeat;
    margin: 0 auto;
    margin-top: 100px;
  }

  #sb_form_q_container::after {
    content: "";
    display: block;
    width: 100%;
    height: 44px;
    background-color: #fff;
    border: 1px solid #dfe1e5;
    border-radius: 24px;
    box-shadow: 0 1px 6px rgba(0, 0, 0, 0.2);
    margin-top: 20px;
    padding: 0 16px;
    box-sizing: border-box;
  }

  /* Add Google search button */
  #sb_form_search_button::before {
    content: "Google Search";
    display: block;
    width: 100%;
    height: 36px;
    background-color: #f2f2f2;
    border: 1px solid #f2f2f2;
    border-radius: 4px;
    color: #3c4043;
    font-size: 14px;
    font-weight: 500;
    line-height: 36px;
    text-align: center;
    margin-top: 20px;
    cursor: pointer;
  }

  /* Adjust page layout */
 html,
 body {
    background-color: #fff;
  }

  #sb_form_q_container {
    width: 100%;
    max-width: 584px;
    margin: 0 auto;
  }
}
